mapper.select:
SELECT p.id, p.plate_no AS plateNo, p.pass_reason AS passReason, p.pass_time AS passTime, p.image_url AS imageUrl, p.status, p.station_id AS stationId, s.name AS stationName, u.nickname AS operatorName, p.operator_time AS operatorTime, p.check_result AS checkResult, p.remark, p.reserve1, p.reserve2, p.creator, p.updater, p.create_time AS createTime, p.update_time AS updateTime FROM pass_record p LEFT JOIN station_info s ON p.station_id = s.id AND s.deleted = 0 LEFT JOIN user_info u ON p.operator_id = u.id AND u.deleted = 0 WHERE p.deleted = 0
AND p.plate_no LIKE CONCAT('%', #{reqVO.plateNo}, '%')
AND p.pass_reason = #{reqVO.passReason}
AND p.pass_time BETWEEN #{reqVO.passTime[0]} AND #{reqVO.passTime[1]}
AND p.status = #{reqVO.status}
AND p.station_id = #{reqVO.stationId}
AND s.name LIKE CONCAT('%', #{reqVO.stationName}, '%')
AND p.operator_id = #{reqVO.operatorId}
AND p.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
AND p.image_url LIKE CONCAT('%', #{reqVO.imageUrl}, '%')
ORDER BY p.id DESC
